<script lang="ts">
import { defineComponent, ref, unref, watch, onMounted, onBeforeUnmount, type PropType } from 'vue'
import QuickPanels from './QuickPanels.vue'
import PreferencesPanel from './PreferencesPanel.vue'
import ThemeCards from './settings/ThemeCards.vue'
import ExportDialog from './documents/ExportDialog.vue'
import { FileText, Image, Check, X, Search, ChevronDown, Share2, Palette } from 'lucide-vue-next'

export default defineComponent({
  name: 'WorkspaceOverlays',
  components: { QuickPanels, PreferencesPanel, ThemeCards, ExportDialog, FileText, Image, Check, X, Search, ChevronDown, Share2, Palette },
  props: { context: { type: Object as PropType<Record<string, any>>, required: true } },
  setup(props) {
    const historyScopeOpen = ref(false)
    function closeHistoryScope(event: Event) {
      if (!(event.target instanceof Element) || !event.target.closest('.history-scope-picker')) historyScopeOpen.value = false
    }
    watch(() => unref(props.context.showHistory), () => { historyScopeOpen.value = false })
    onMounted(() => document.addEventListener('pointerdown', closeHistoryScope))
    onBeforeUnmount(() => document.removeEventListener('pointerdown', closeHistoryScope))
    return Object.assign({}, props.context, { historyScopeOpen })
  }
})
</script>

<template>
<QuickPanels :commands-open="showCommands" :reference-open="showReference" v-model:reference-tab="referenceTab" :commands="commands" :shortcuts="shortcutGuide" @close-commands="showCommands = false" @close-reference="showReference = false"/>

    <div v-if="imagePropertyDraft" class="modal-backdrop" @click.self="imagePropertyDraft = null"><div class="properties-modal" role="dialog" aria-modal="true" :aria-label="$t('图片属性')"><div class="modal-head"><h2>{{ $t('图片属性') }}</h2><button class="icon-button" :aria-label="$t('关闭图片属性')" @click="imagePropertyDraft = null"><X :size="19"/></button></div><div class="properties-content image-property-fields"><label>{{ $t('替代文本') }} <input v-model="imagePropertyDraft.alt" :aria-label="$t('图片替代文本')"/></label><label>{{ $t('标题') }} <input v-model="imagePropertyDraft.title" :aria-label="$t('图片标题')"/></label><label>{{ $t('路径') }} <input v-model="imagePropertyDraft.path" :aria-label="$t('图片路径')"/></label><label>{{ $t('本机显示宽度（px）') }} <input v-model.number="imagePropertyDraft.width" type="number" min="16" max="2000" :aria-label="$t('图片显示宽度')"/></label><div class="table-edit-actions"><button @click="imagePropertyDraft = null">{{ $t('取消') }}</button><button @click="saveImageProperties">{{ $t('应用') }}</button></div></div></div></div>




    <div v-if="showSpellcheck" class="utility-popover" :style="{ top: `${utilityPopoverPosition.top}px`, left: `${utilityPopoverPosition.left}px` }"><div class="properties-modal" role="dialog" aria-modal="true" :aria-label="$t('拼写检查结果')"><div class="modal-head"><h2>{{ $t('拼写检查') }}</h2><button class="icon-button" :aria-label="$t('关闭拼写检查')" @click="showSpellcheck = false"><X :size="19"/></button></div><div class="spellcheck-results"><p v-if="!spellResults.length">{{ $t('未发现拼写错误') }}</p><div v-for="(item, index) in spellResults" :key="`${item.offset}-${index}`" class="spellcheck-item"><button @click="locateMisspelling(item)"><strong>{{ item.word }}</strong><span>{{ item.suggestions.join('、') || '查看位置' }}</span></button></div></div></div></div>


    <PreferencesPanel :context="preferencesContext"/>
    <div v-if="showThemes" class="modal-backdrop theme-backdrop" @click.self="showThemes = false"><div class="theme-modal" role="dialog" aria-modal="true" :aria-label="$t('主题')"><div class="theme-modal-head"><Palette :size="19" aria-hidden="true"/><span class="reference-esc" aria-hidden="true">ESC</span></div><div class="theme-modal-body"><ThemeCards :themes="allThemes" :model-value="themeName" @update:model-value="selectTheme" @remove="removeTheme" @add="addTheme"/></div></div></div>



    <ExportDialog :open="showExport" :share-open="showShare" :filename="activeDoc.path" :revision="exportRevision" :busy="exportBusy" :is-tauri="isTauri" :prepare="prepareExport" @close="showExport = false" @download="download" @share="toggleShare" @stop-share="stopShare"><template #share><div class="share-body"><p v-if="shareBusy">{{ $t('正在生成链接…') }}</p><template v-else-if="shareUrl"><img :src="shareQr" :alt="$t('局域网分享二维码')"/><p>{{ $t('局域网扫码查看') }}</p></template></div></template><template #share-actions><button :disabled="shareBusy || !shareUrl" @click="copyShareUrl()">{{ $t('复制链接') }}</button></template></ExportDialog>
    <div v-if="showSnippetMenu" class="utility-popover compact-utility-popover" :style="{ top: `${utilityPopoverPosition.top}px`, left: `${utilityPopoverPosition.left}px` }" role="dialog" :aria-label="$t('片段')"><div class="utility-head"><strong>{{ $t('片段') }}</strong><button class="icon-button" :aria-label="$t('关闭片段')" @click="showSnippetMenu = false"><X :size="15"/></button></div><button v-for="item in snippets" :key="item.id" class="utility-list-button" @click="editor?.insertSnippet(item.content); showSnippetMenu = false">{{ item.name }}</button><p v-if="!snippets.length" class="utility-empty">{{ $t('在设置中添加片段后，可从这里插入') }}</p></div>
    <div v-if="showHistory" class="modal-backdrop history-backdrop" @click.self="showHistory = false"><div class="history-popover" role="dialog" aria-modal="true" :aria-label="$t('历史版本')"><div class="command-search history-search"><div class="history-scope-picker"><button class="history-scope-trigger" :aria-label="$t('搜索范围')" :aria-expanded="historyScopeOpen" aria-haspopup="menu" @click="historyScopeOpen = !historyScopeOpen"><span>{{ historySearchScope === 'added' ? '+' : historySearchScope === 'removed' ? '−' : '±' }}</span><ChevronDown :size="12"/></button><div v-if="historyScopeOpen" class="history-scope-menu" role="menu" :aria-label="$t('搜索范围')"><button v-for="scope in [{ value: 'all', label: '全部' }, { value: 'removed', label: '− 删除' }, { value: 'added', label: '+ 新增' }]" :key="scope.value" role="menuitemradio" :aria-checked="historySearchScope === scope.value" @click="historySearchScope = scope.value; historyScopeOpen = false"><span>{{ $t(scope.label) }}</span><Check v-if="historySearchScope === scope.value" :size="14"/></button></div></div><Search :size="18"/><input v-model="historySearch" type="search" :placeholder="$t('搜索差异')" :aria-label="$t('搜索差异')"/><button class="history-close reference-esc" :aria-label="$t('关闭历史版本')" @click="showHistory = false">ESC</button></div><div class="history-popover-head"><strong>{{ $t('历史版本 ·') }} {{ activeDoc.path.split('/').pop() }}</strong></div><p v-if="!historyVersions.length" class="history-empty">{{ $t('保存文件后，可在这里查看历史版本。') }}</p><p v-if="historySearchError" class="history-empty">{{ historySearchError }}</p><p v-else-if="!historySearchBusy && historyVersions.length && !filteredHistoryVersions.length" class="history-empty">{{ $t('没有匹配的差异') }}</p><div class="history-list" :aria-busy="historySearchBusy"><div v-for="item in filteredHistoryVersions" :key="item.id" class="history-entry"><div class="history-item"><span class="history-date">{{ new Date(item.created).toLocaleString('zh-CN') }}</span><button class="history-compare-toggle" :aria-expanded="selectedHistory?.id === item.id" @click="compareHistory(item.id)">{{ $t('差异') }}</button><button class="history-restore" :disabled="historyBusy || dirtyIds.includes(activeId) || conflictedIds.includes(activeId)" @click="restoreHistory(item.id)">{{ $t('恢复') }}</button></div><div v-if="selectedHistory?.id === item.id" class="history-compare"><div v-if="!selectedHistoryDiff.length" class="history-identical">{{ $t('无差异') }}</div><div v-if="selectedHistoryDiff.length && !filteredHistoryDiff.length" class="history-identical">{{ $t('没有匹配的差异') }}</div><div class="history-diff-window"><span v-for="(row, rowIndex) in filteredHistoryDiff" :key="rowIndex" class="history-diff-row" :class="`history-diff-${row.kind}`"><span class="history-diff-number">{{ row.oldLine ?? '' }}</span><span class="history-diff-number">{{ row.newLine ?? '' }}</span><span class="history-diff-mark">{{ row.kind === 'added' ? '+' : row.kind === 'removed' ? '−' : ' ' }}</span><span><template v-for="(part, partIndex) in row.parts" :key="partIndex"><mark v-if="part.match">{{ part.text }}</mark><template v-else>{{ part.text }}</template></template></span></span></div></div></div></div></div></div>
    <div v-if="repairPreview" class="modal-backdrop"><div class="file-state-modal" role="dialog" aria-modal="true" :aria-label="$t('资源修复预览')"><h2>{{ $t('资源修复预览') }}</h2><pre>− {{ repairPreview.beforeLine }}&#10;+ {{ repairPreview.afterLine }}</pre><p>{{ $t('仅修改此处链接，保存文件后生效。') }}</p><div class="modal-actions"><button @click="repairPreview = null">{{ $t('取消') }}</button><button class="primary" @click="applyResourceRepair">{{ $t('修改链接') }}</button></div></div></div>
    <div v-if="missingResources" class="modal-backdrop" @click.self="missingResources = null"><div class="file-state-modal" role="dialog" aria-modal="true" :aria-label="$t('失效链接与图片')"><h2>{{ $t('失效链接与图片') }}</h2><p v-if="!missingResources.length">{{ $t('未发现失效的链接或图片。') }}</p><div v-for="(item, index) in missingResources" :key="index" class="missing-resource-row"><button @click="locateMissingResource(item)"><strong>{{ item.source }}:{{ item.line }}</strong><span>{{ item.target }} → {{ item.resolved }}</span></button><button @click="previewResourceRepair(item)">{{ $t('修复') }}</button></div><div class="modal-actions"><button @click="missingResources = null">{{ $t('关闭') }}</button></div></div></div>
    <div v-if="closeTabDialog" class="modal-backdrop" @keydown.esc.prevent="finishCloseTab(null)"><div class="file-state-modal compact-confirm-modal" role="dialog" aria-modal="true" aria-labelledby="close-tab-title" aria-describedby="close-tab-description"><h2 id="close-tab-title">{{ $t('保存对“') }}{{ closeTabDialog.name }}{{ $t('”的修改？') }}</h2><p id="close-tab-description">{{ $t('丢弃后，未保存的修改将丢失。') }}</p><div class="modal-actions"><button @click="finishCloseTab('discard')">{{ $t('丢弃') }}</button><button autofocus @click="finishCloseTab(null)">{{ $t('取消') }}</button><button class="primary" @click="finishCloseTab('save')">{{ $t('保存') }}</button></div></div></div>
    <div v-if="fileDialog" class="modal-backdrop"><form class="file-state-modal compact-confirm-modal" role="dialog" aria-modal="true" :aria-label="fileDialog.title" @submit.prevent="finishFileAction(true)"><h2>{{ fileDialog.title }}</h2><input v-if="!fileDialog.confirm" v-model="fileDialog.value" autofocus :aria-label="fileDialog.title"/><div class="modal-actions"><button type="button" @click="finishFileAction(false)">{{ $t('取消') }}</button><button class="primary" type="submit">{{ fileDialog.confirm ? $t('删除') : $t('确定') }}</button></div></form></div>
    <div v-if="conflict" class="modal-backdrop"><div class="file-state-modal compact-confirm-modal" role="dialog" aria-modal="true" :aria-label="$t('加载文件更新')"><h2>{{ $t('加载文件更新？') }}</h2><p>{{ $t('加载磁盘上的最新内容。当前未保存的修改将被替换。') }}</p><div class="modal-actions"><button @click="keepCurrentEditing">{{ $t('保留当前内容') }}</button><button class="primary" :disabled="conflict.disk.missing" @click="reloadAfterConflict()">{{ $t('加载更新') }}</button></div></div></div>
    <div v-if="toast" class="toast"><Check :size="15"/> {{ $t(toast) }}</div>
    <Teleport to="body"><div v-if="fileDragGhost" class="topbar-drag-ghost" :class="{ 'ghost-dark': themeName === '深海', 'ghost-sand': themeName === '陶纸' }" :style="{ left: `${fileDragGhost.x}px`, top: `${fileDragGhost.y}px` }"><FileText :size="15"/><span>{{ fileDragGhost.name }}</span></div></Teleport>
</template>
